-- Logical relational schema. CSV exports are generated by src/planner.py.
CREATE TABLE Program (
  program_id VARCHAR(10) PRIMARY KEY, program_name VARCHAR(120) NOT NULL,
  department VARCHAR(80) NOT NULL, degree_level VARCHAR(2) NOT NULL CHECK(degree_level IN ('UG','PG')),
  status VARCHAR(12) NOT NULL, effective_from DATE NOT NULL, effective_to DATE NULL
);
CREATE TABLE Course (
  course_id VARCHAR(10) PRIMARY KEY, program_id VARCHAR(10) NOT NULL REFERENCES Program(program_id),
  course_code VARCHAR(12) UNIQUE NOT NULL, course_name VARCHAR(120) NOT NULL,
  course_type VARCHAR(10) NOT NULL CHECK(course_type IN ('CORE','ELECTIVE')),
  credits INT NOT NULL CHECK(credits BETWEEN 1 AND 6), required_skill VARCHAR(20) NOT NULL,
  weekly_hours INT NOT NULL CHECK(weekly_hours>0), status VARCHAR(12) NOT NULL
);
CREATE TABLE Prerequisite (
  prerequisite_id VARCHAR(12) PRIMARY KEY, course_id VARCHAR(10) NOT NULL REFERENCES Course(course_id),
  required_course_id VARCHAR(10) NOT NULL REFERENCES Course(course_id), minimum_grade VARCHAR(2) NOT NULL,
  effective_from DATE NOT NULL, effective_to DATE NULL, UNIQUE(course_id,required_course_id)
);
CREATE TABLE StudentPlan (
  student_plan_id VARCHAR(12) PRIMARY KEY, student_ref VARCHAR(16) UNIQUE NOT NULL,
  program_id VARCHAR(10) NOT NULL REFERENCES Program(program_id), term VARCHAR(12) NOT NULL,
  year_of_study INT NOT NULL CHECK(year_of_study BETWEEN 1 AND 8), plan_status VARCHAR(12) NOT NULL
);
CREATE TABLE RegistrationInterest (
  registration_interest_id VARCHAR(12) PRIMARY KEY, student_plan_id VARCHAR(12) NOT NULL REFERENCES StudentPlan(student_plan_id),
  course_id VARCHAR(10) NOT NULL REFERENCES Course(course_id), term VARCHAR(12) NOT NULL,
  interest_date DATE NOT NULL, priority INT NOT NULL CHECK(priority BETWEEN 1 AND 3),
  interest_status VARCHAR(12) NOT NULL CHECK(interest_status IN ('CONFIRMED','WITHDRAWN'))
);
CREATE TABLE Faculty (
  faculty_id VARCHAR(10) PRIMARY KEY, faculty_name VARCHAR(100) NOT NULL,
  employment_type VARCHAR(12) NOT NULL, weekly_workload_limit INT NOT NULL CHECK(weekly_workload_limit>0),
  status VARCHAR(12) NOT NULL
);
CREATE TABLE FacultySkill (
  faculty_skill_id VARCHAR(12) PRIMARY KEY, faculty_id VARCHAR(10) NOT NULL REFERENCES Faculty(faculty_id),
  skill_code VARCHAR(20) NOT NULL, proficiency VARCHAR(12) NOT NULL,
  effective_from DATE NOT NULL, effective_to DATE NULL, UNIQUE(faculty_id,skill_code,effective_from)
);
CREATE TABLE Availability (
  availability_id VARCHAR(12) PRIMARY KEY, faculty_id VARCHAR(10) NOT NULL REFERENCES Faculty(faculty_id),
  term VARCHAR(12) NOT NULL, day VARCHAR(3) NOT NULL, available BOOLEAN NOT NULL, leave_flag BOOLEAN NOT NULL,
  UNIQUE(faculty_id,term,day)
);
CREATE TABLE Room (
  room_id VARCHAR(10) PRIMARY KEY, building VARCHAR(80) NOT NULL, room_name VARCHAR(30) NOT NULL,
  capacity INT NOT NULL CHECK(capacity>0), room_type VARCHAR(12) NOT NULL, status VARCHAR(12) NOT NULL
);
CREATE TABLE Section (
  section_id VARCHAR(18) PRIMARY KEY, course_id VARCHAR(10) NOT NULL REFERENCES Course(course_id),
  term VARCHAR(12) NOT NULL, room_id VARCHAR(10) NOT NULL REFERENCES Room(room_id),
  capacity INT NOT NULL CHECK(capacity>0), planned_enrollment INT NOT NULL,
  section_status VARCHAR(12) NOT NULL
);
CREATE TABLE WorkloadAssignment (
  workload_assignment_id VARCHAR(18) PRIMARY KEY, section_id VARCHAR(18) NOT NULL REFERENCES Section(section_id),
  faculty_id VARCHAR(10) NOT NULL REFERENCES Faculty(faculty_id), weekly_hours INT NOT NULL CHECK(weekly_hours>0),
  assignment_status VARCHAR(12) NOT NULL, UNIQUE(section_id,faculty_id)
);
-- N:M: Program-Course via Course; Faculty-Course skill relation via FacultySkill.
-- Event/history extension: append-only state events, never overwrite prior state.
CREATE TABLE StateEvent (
  event_id BIGINT PRIMARY KEY, entity_type VARCHAR(40) NOT NULL, entity_id VARCHAR(24) NOT NULL,
  from_state VARCHAR(20), to_state VARCHAR(20) NOT NULL, event_time TIMESTAMP NOT NULL,
  actor_role VARCHAR(30) NOT NULL, reason VARCHAR(250)
);
